struct Person {
    string name;
    int age;
};
Person p = {"Alice", 25};
cout << p.name << endl; // 输出 Alice

class Person {
private:
    string name;
    int age;
public:
    Person(string n, int a) : name(n), age(a) {}
    void printInfo() {
        cout << "Name: " << name << ", Age: " << age << endl;
    }
};
Person p("Bob", 30);
p.printInfo(); // 输出: Name: Bob, Age: 30

struct Node {
    int data;
    Node* next;
};
Node* head = nullptr;
Node* newNode = new Node{10, nullptr};
head = newNode; // 插入新节点

stack<int> s;
s.push(1);
s.push(2);
cout << s.top(); // 输出 2
s.pop();

queue<int> q;
q.push(1);
q.push(2);
cout << q.front(); // 输出 1
q.pop();

deque<int> dq;
dq.push_back(1);
dq.push_front(2);
cout << dq.front(); // 输出 2
dq.pop_front();

unordered_map<string, int> hashTable;
hashTable["apple"] = 10;
cout << hashTable["apple"]; // 输出 10

map<string, int> myMap;
myMap["apple"] = 10;
cout << myMap["apple"]; // 输出 10

set<int> s;
s.insert(1);
s.insert(2);
cout << *s.begin(); // 输出 1

vector<int> v;
v.push_back(1);
v.push_back(2);
cout << v[0]; // 输出 1
